import * as Sentry from '@sentry/react-native';
import * as SecureStore from 'expo-secure-store';

const KEY = 'gloceries_partner_monitoring_check_1_0_2';
// Only the internal release-validation profile opts in. No test error is
// generated by the production AAB or by a development build.
export async function runReleaseMonitoringCheck(): Promise<void> {
  if (__DEV__ || process.env.EXPO_PUBLIC_SENTRY_SMOKE_TEST !== 'true' || !process.env.EXPO_PUBLIC_SENTRY_DSN) return;
  if (await SecureStore.getItemAsync(KEY)) return;
  const eventId = Sentry.captureException(new Error('Gloceries Partner release monitoring check'), {
    tags: { verification: 'partner-release-1.0.2' },
  });
  const flushed = await Sentry.flush();
  if (flushed) await SecureStore.setItemAsync(KEY, eventId);
  // Only the event identifier is logged, so it can be matched in Sentry.
  console.info('Partner monitoring verification', { eventId, flushed });
}
